target.command:
cd /home/john/mynotes/deterministic_equidistribution_theory/c_suite/out_large
echo "### Sectors that win as argmax in shadow-bearing windows, with their E gap_ratio ###"
awk -F, '
  FNR==NR { if(!/^#/ && $1!="Q" && $6!="trivial") g[$1","$7","$5]=$10; next }
  !/^#/ && $1!="window_id" && NF>=14 && $14==1 {
     key=$7","$8","$9; gr=(key in g)?g[key]:-1;
     cnt[key]++; sw[key]+=$6; grv[key]=gr;
     if($4>=64){ lcnt[key]++; lsw[key]+=$6 }
  }
  END{
     printf "%-16s %8s %9s %10s %8s\n","Q,char,s","nwin","mean|W|","gap_ratio","nlong";
     for(k in cnt) printf "%-16s %8d %9.4f %10.4f %8d\n",k,cnt[k],sw[k]/cnt[k],grv[k],lcnt[k]+0;
  }' spectral_gaps.csv shadow_search.csv | sort -t, -k1,1n | sort -k2 -nr -t' ' | head -25
